import { useNumberField } from '@react-aria/numberfield';
import { useNumberFieldState } from '@react-stately/numberfield';
import React, {
  ChangeEvent,
  KeyboardEvent,
  KeyboardEventHandler,
  forwardRef,
  useImperativeHandle,
  useMemo,
  useRef,
} from 'react';
import styled, { CSSObject, css } from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Easings from '@dynatrace/strato-design-tokens/easings';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Timings from '@dynatrace/strato-design-tokens/timings';
import { getRegionalFormat } from '@dynatrace-sdk/user-preferences';

import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { _useControllableState } from '../../core/hooks/useControllableState.js';
import type { CSSFocusStylesObject } from '../../core/hooks/useFocusRing.js';
import { useFocusRing } from '../../core/hooks/useFocusRing.js';
import { _useFormControlState } from '../../core/hooks/useFormControlState.js';
import type { FocusEvents } from '../../core/types/events.js';
import { mergeProps as _mergeProps } from '../../core/utils/merge-props.js';
import { getTextStyle } from '../../core/utils/styles/text-styles.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import type { BaseInputProps } from '../_base-input/BaseInput.js';
import { Hint } from '../forms-core/components/hint/Hint.js';
import { _useFormFieldContext } from '../forms-core/hooks/useFormFieldContext.js';
import { FormFieldAction } from '../forms-core/state/formfield-state-reducer.js';
import { autofillCss, useAutofillEvent } from '../hooks/useAutofillEvent.js';
import { _useInputHint } from '../hooks/useInputHint.js';
import type { FormControlRef } from '../shared-types.js';

// #region Typings
export type NumberInputControlledProps = {
  /** The default value of the input */
  defaultValue?: never;
  /** The value of the input. */
  value?: number | null;
};

export type NumberInputUncontrolledProps = {
  /** The default value of the input */
  defaultValue?: number;
  /** The value of the input. */
  value?: never;
};

export interface NumberInputLimitProps {
  /** Minimum amount of the input. */
  min?: number | string;
  /** Maximum amount of the input. */
  max?: number | string;
  /** Defines the step size in which increments/decrements can be performed on the input. */
  step?: number;
}

export type NumberInputProps = Pick<
  BaseInputProps,
  | 'autoComplete'
  | 'name'
  | 'controlState'
  | 'id'
  | 'placeholder'
  | 'disabled'
  | 'required'
  | 'readOnly'
  | 'minLength'
  | 'maxLength'
  | 'pattern'
  | 'onKeyUp'
  | 'aria-label'
  | 'aria-labelledby'
  | 'aria-describedby'
  | 'aria-details'
  | 'className'
  | 'style'
  | 'data-testid'
> &
  (NumberInputUncontrolledProps | NumberInputControlledProps) &
  FocusEvents &
  NumberInputLimitProps & {
    /** Handler that is called when a key is pressed. */
    onKeyDown?: KeyboardEventHandler<HTMLInputElement>;
    /** Handler that is called when the value changes. */
    onChange?: (value: number | null) => void;
  };

type StyledTextInputContainerProps = Pick<
  BaseInputProps,
  'disabled' | 'readOnly'
> & {
  $isAutoFilled: boolean;
};
// #endregion

// #region StyledComponents
const StyledTextWrapper = /* @__PURE__ */ styled(Flex)<{
  $hasError: boolean;
  disabled: boolean;
}>(({ $hasError, disabled }) => {
  const tokenByError = $hasError ? 'Critical' : 'Neutral';
  const animationStyles = {
    transitionProperty: 'box-shadow, border-color',
    transitionDuration: Timings.Fast.Quick,
    transitionTimingFunction: `${Easings.FastInSlowOut}, ${Easings.Decelerate}`,
  };

  const inputVariantStyle: CSSObject = disabled
    ? {}
    : {
        '.input-container': {
          backgroundColor: Colors.Background.Field[tokenByError].Emphasized,
          ...animationStyles,
        },
        '&:hover .input-container, &:active .input-container': {
          backgroundColor: Colors.Background.Field[tokenByError].Emphasized,
        },
        '& .input-container:hover ': {
          backgroundColor:
            Colors.Background.Field[tokenByError].EmphasizedHover,
        },
        '& .input-container:active': {
          backgroundColor:
            Colors.Background.Field[tokenByError].EmphasizedActive,
        },
      };

  const disabledStyles = disabled
    ? {
        '.input-container': {
          backgroundColor: Colors.Background.Field[tokenByError].Disabled,
          ...animationStyles,
        },
      }
    : {};

  return {
    '& > *:first-child': {
      borderTopLeftRadius: Borders.Radius.Field.Default,
      borderBottomLeftRadius: Borders.Radius.Field.Default,
    },
    '& > *:last-child': {
      borderTopRightRadius: Borders.Radius.Field.Default,
      borderBottomRightRadius: Borders.Radius.Field.Default,
    },
    ...inputVariantStyle,
    ...disabledStyles,
  };
});

const StyledTextInputContainer = /* @__PURE__ */ styled('div')<
  StyledTextInputContainerProps & { $focusStyle?: CSSFocusStylesObject }
>(({ $isAutoFilled, readOnly, $focusStyle }) => {
  const autoFilledStyle = $isAutoFilled
    ? {
        borderColor: Colors.Text.Primary.Default,
        backgroundColor: Colors.Background.Field.Primary.Emphasized,

        'span svg': {
          fill: Colors.Text.Primary.Default,
        },
      }
    : {};

  const readOnlyStyles = readOnly
    ? {
        backgroundColor: Colors.Background.Field.Neutral.Disabled,
      }
    : {};

  return {
    position: 'relative',
    display: 'flex',
    minWidth: 0,
    flexGrow: 1,
    alignItems: 'center',
    boxSizing: 'border-box',
    paddingLeft: Spacings.Size12,
    paddingRight: Spacings.Size12,
    ...$focusStyle,
    ...autoFilledStyle,
    ...readOnlyStyles,
  };
});

type StyledTextInputProps = Pick<BaseInputProps, 'disabled'> & {
  $hasError: boolean;
};

// FIXME: When using keyframes (coming in from the autofill), styled components complains about the CSSObject usage. We might be able to enhance this later.
const StyledTextInput = /* @__PURE__ */ styled('input')<StyledTextInputProps>`
  display: block;
  text-overflow: ellipsis;
  appearance: none;
  background: transparent;
  border: none;

  padding: 0;
  margin-top: ${Spacings.Size6};
  margin-bottom: ${Spacings.Size6};

  flex-grow: 1;
  align-self: stretch;

  min-width: 0;
  color: ${Colors.Text.Neutral.Default};
  ${getTextStyle('base')}

  &:read-only {
    cursor: not-allowed;
  }

  &:focus {
    outline: none; /* Clears user agent style */
  }

  &::placeholder {
    color: ${Colors.Text.Neutral.Subdued};
  }

  ${autofillCss}

  &:disabled,
  &:disabled::placeholder,
  &:disabled:-webkit-autofill {
    -webkit-text-fill-color: ${Colors.Text.Neutral.Disabled};
    color: ${Colors.Text.Neutral.Disabled};
  }

  ${({ $hasError, disabled }) =>
    $hasError &&
    !disabled &&
    css`
      color: ${Colors.Text.Critical.Default};
      &::placeholder,
      &:-webkit-autofill {
        -webkit-text-fill-color: ${Colors.Text.Critical.Default};
        color: ${Colors.Text.Critical.Default};
      }
    `}
`;
// #endregion

/**
 * NumberInputBase component. This is necessary in order to correctly call onChange with undefined on blur, which is otherwise set to NaN by react-stately.
 */
export const NumberInputBase = /* @__PURE__ */ forwardRef<
  FormControlRef<HTMLDivElement>,
  NumberInputProps
>((props, forwardedRef) => {
  const {
    id: numberInputPropId,
    defaultValue,
    value,
    name,
    onChange,
    disabled: isDisabled,
    readOnly: isReadOnly,
    required: isRequired,
    min: minValueNumberLike,
    max: maxValueNumberLike,
    step,
    placeholder,
    controlState,
    onKeyUp,
    onKeyDown,
    onBlur,
    onFocus,
    onFocusChange,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId = 'number-input-root',
    ...remainingProps
  }: NumberInputProps = props;

  const { 'aria-labelledby': ariaLabelledBy, ...remainingAriaProps } =
    _useAriaLabelingProps(remainingProps);
  const locale = useMemo(() => getRegionalFormat(), []);

  // Cast min and max to number since we accept string as well to better match native number inputs
  const minValue = !isNaN(Number(minValueNumberLike))
    ? Number(minValueNumberLike)
    : undefined;
  const maxValue = !isNaN(Number(maxValueNumberLike))
    ? Number(maxValueNumberLike)
    : undefined;

  const numberInputValue = value === null || value === undefined ? NaN : value; // necessary so we can clear the inputValue; otherwise, it snaps back to the previously valid inputValue

  const {
    controlId,
    required: contextRequired,
    disabled: contextDisabled,
    dispatch,
  } = _useFormFieldContext();

  if (
    (numberInputPropId !== undefined && numberInputPropId !== controlId) ||
    (isDisabled !== undefined && isDisabled !== contextDisabled) ||
    (isRequired !== undefined && isRequired !== contextRequired)
  ) {
    dispatch?.({
      type: FormFieldAction.UPDATE,
      payload: {
        id: numberInputPropId,
        disabled: isDisabled,
        required: isRequired,
      },
    });
  }

  const contextId = numberInputPropId || controlId;
  const disabled = isDisabled || contextDisabled;
  const required = isRequired || contextRequired;

  const state = useNumberFieldState({
    value: numberInputValue,
    onChange,
    placeholder,
    minValue,
    maxValue,
    step,
    isDisabled: disabled,
    isReadOnly,
    isRequired: required,
    locale,
  });

  const inputRef = useRef<HTMLInputElement>(null);
  const wrapperRef = useRef<HTMLDivElement>(null);

  useImperativeHandle(
    forwardedRef,
    (): FormControlRef<HTMLDivElement> => ({
      element: wrapperRef.current,
      inputRef: inputRef.current,
      focus() {
        inputRef.current?.focus();
      },
    }),
    [],
  );

  const { inputProps } = useNumberField(
    {
      value: numberInputValue,
      onChange,
      id: contextId,
      placeholder,
      minValue,
      maxValue,
      step,
      isDisabled: disabled,
      isReadOnly,
      isRequired: required,
      onKeyUp,
      onKeyDown,
      onBlur,
      onFocus,
      onFocusChange,
      // we pass the aria-labelledBy only if there's no aria-label, because the useNumberField would add aria-labelledby
      // with 2 ids and append the input text to its aria-label otherwise, breaking the getByLabelText selectors in tests otherwise
      'aria-labelledby': remainingAriaProps['aria-label']
        ? undefined
        : ariaLabelledBy,
      ...remainingAriaProps, // passing the aria props here prevents unnecessary react-aria warnings when aria-labelling props are already set
    },
    state,
    inputRef,
  );
  let inputDefaultValue: string | undefined;

  if (defaultValue !== undefined) {
    inputDefaultValue = defaultValue.toString();
  } else {
    inputDefaultValue =
      value === undefined && !onChange
        ? '' // this prevents warnings about switching from uncontrolled to controlled inputs when no value or defaultValue is set, but onChange used without a value/defaultValue will still throw it
        : undefined;
  }

  const {
    value: inputPropsValue,
    type,
    id,
    readOnly = false,
    role,
    onKeyDown: onKeyDownReactAria,
    ...remainingInputProps
  } = inputProps;

  const [inputValue, setInputValue] = _useControllableState({
    defaultValue: inputDefaultValue,
    value: inputPropsValue?.toString(),
  });

  const [hasError, hint] = _useFormControlState(controlState);
  const {
    containerProps,
    inputProps: inputHintAriaProps,
    hintProps,
  } = _useInputHint({
    hint,
    hasError,
  });

  const { isAutoFilled, onAnimationStart } = useAutofillEvent();

  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    remainingInputProps?.onChange?.(event);
    setInputValue(event.target.value);
  };

  const { focusProps, focusStyles } = useFocusRing({
    variant: hasError ? 'critical' : 'neutral',
    ignoreModality: true,
  });

  //TODO: replace this with the BaseInput once the rework is done and we no longer depend on react-aria. This introduced the limitation of passing the inputRef from the BaseInput to the NumberInputBase, as it's initially null and useNumberField instantly breaks instead of waiting for failing gracefully and then resetting the ref on the next render
  return (
    <Flex
      gap={4}
      flexDirection="column"
      data-testid={dataTestId}
      ref={wrapperRef}
      className={consumerClassName}
      style={consumerStyle}
      {...containerProps}
    >
      <StyledTextWrapper
        gap={2}
        disabled={disabled}
        alignItems="center"
        $variant="default"
        $hasError={hasError}
      >
        <StyledTextInputContainer
          readOnly={false}
          disabled={disabled}
          className="input-container"
          $isAutoFilled={isAutoFilled}
          $focusStyle={focusStyles}
        >
          <StyledTextInput
            id={id}
            ref={inputRef}
            type="text"
            role={role}
            data-testid="number-input"
            onChange={handleInputChange}
            onAnimationStart={onAnimationStart}
            $hasError={hasError}
            disabled={disabled}
            readOnly={readOnly}
            {...(_mergeProps(
              remainingInputProps,
              remainingProps,
              focusProps,
              inputHintAriaProps,
            ) as unknown as Record<string, unknown>)}
            name={name}
            required={required} // react-aria only sets aria-required in the remainingInputProps, so we need to override it with the context prop here
            value={inputValue}
            // react-aria prevents default events, so it behaves differently from our TextInput, which has some undesired issues - see ADES-3971 and https://github.com/adobe/react-spectrum/issues/2803
            onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
              if (
                (e.key === 'Home' && minValue === undefined) ||
                (e.key === 'End' && maxValue === undefined)
              ) {
                onKeyDown?.(e);
                return; // opt out of using react-aria's keydown logic in this case, because it would prevent default behavior (moving the cursor to the front/end with Home/End)
              }

              onKeyDownReactAria?.(e); // we still need to use react aria's events when we do have a min/max (then the value will be snapped to these when pressing Home/End) or for incrementing/decrementing the value on pressing Up/Down keys, but these will no longer be necessary as soon as we implement the spin button
            }}
          />
        </StyledTextInputContainer>
      </StyledTextWrapper>
      <Hint hasError={hasError} disabled={disabled} {...hintProps}>
        {hint}
      </Hint>
    </Flex>
  );
});

(
  NumberInputBase as typeof NumberInputBase & { displayName: string }
).displayName = 'NumberInputBase';
